import pandas as pd
import numpy as np

# Load the data
trip_data = pd.read_csv('chunks_csv/cyclehire_w004.csv')
adjacency_list = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratio for each borough
self_containment_ratios = trip_data.groupby('StartBorough')['EndBorough'].value_counts().unstack().fillna(0)
self_containment_ratios = self_containment_ratios.div(self_containment_ratios.sum(axis=1), axis=0)

# Prepare borough adjacency list
adjacency_list = adjacency_list.set_index('borough').to_dict(orient='index')
adjacent_boroughs = {}
for borough, neighbors in adjacency_list.items():
    adjacent_boroughs[borough] = neighbors['neighbor']

# Calculate the spatial autocorrelation
distances = {}
for i in self_containment_ratios.index:
    distances[i] = {}
    for j in self_containment_ratios.index:
        distances[i][j] = np.sqrt((i - j) ** 2)

weights = {}
for i in self_containment_ratios.index:
    weights[i] = {}
    for j in self_containment_ratios.index:
        if i in adjacent_boroughs and j in adjacent_boroughs and i != j:
            weights[i][j] = 1 / distances[i][j]
        else:
            weights[i][j] = 0

# Compute Moran's I statistic
moran_i = 0
for i in self_containment_ratios.index:
    for j in self_containment_ratios.index:
        if i in adjacent_boroughs and j in adjacent_boroughs and i != j:
            moran_i += (self_containment_ratios.loc[i] - self_containment_ratios.mean()) * (self_containment_ratios.loc[j] - self_containment_ratios.mean()) * weights[i][j]

# Perform permutation test to determine significance
data_points_used = len(self_containment_ratios)
observed_moran_i = moran_i
p_value = 0
for _ in range(500):
    shuffled_ratios = self_containment_ratios.copy()
    shuffled_ratios = shuffled_ratios.sample(frac=1)
    shuffled_moran_i = 0
    for i in self_containment_ratios.index:
        for j in self_containment_ratios.index:
            if i in adjacent_boroughs and j in adjacent_boroughs and i != j:
                shuffled_moran_i += (shuffled_ratios.loc[i] - self_containment_ratios.mean()) * (shuffled_ratios.loc[j] - self_containment_ratios.mean()) * weights[i][j]
    if shuffled_moran_i >= observed_moran_i:
        p_value += 1

p_value /= 500

# Determine clustering
if p_value < 0.05:
    print(f'FINAL ANSWER: CLUSTERED (statistical method = Moran\'s I, p = {p_value})')
else:
    print(f'FINAL ANSWER: NOT CLUSTERED (statistical method = Moran\'s I, p = {p_value})')
print(f'data_points_used = {data_points_used}')
